with lines as (select id, plan, effective_from, currency, tier_value from price_tiers lateral view outer explode(discounts) li as tier_value) select id, plan, effective_from, currency, tier_value, dense_rank() over w_hist tier_value_dense_rank, percent_rank() over (order by tier_value nulls first) tier_value_percent_rank, dense_rank() over (partition by plan, currency order by tier_value desc nulls last) tier_value_dense_rank_2, dense_rank() over (partition by currency order by tier_value desc nulls first) tier_value_dense_rank_3 from lines window w_hist as (partition by plan, currency order by tier_value);
